export function installResizableLayout(){
 const key='livrostudio-panel-layout-v1';let prefs={};try{prefs=JSON.parse(localStorage.getItem(key)||'{}');}catch{}if(!prefs||typeof prefs!=='object'||Array.isArray(prefs))prefs={};const handles=[];
 function persist(){try{localStorage.setItem(key,JSON.stringify(prefs));}catch{}}
 function grip({target,name,axis='y',min=80,max=700,apply,insert,reverse=false}){const handle=document.createElement('div');handle.className='panel-divider '+(axis==='x'?'vertical':'horizontal');handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-orientation',axis==='x'?'vertical':'horizontal');handle.setAttribute('aria-label',name);handle.title=name+' · arraste para ajustar; dois cliques para restaurar';const id=name;const set=value=>{value=Math.round(Math.max(min,Math.min(typeof max==='function'?max():max,value)));prefs[id]=value;apply(value);handle.setAttribute('aria-valuenow',value);};if(Number.isFinite(prefs[id]))set(prefs[id]);insert(handle);handle.setAttribute('aria-valuemin',min);handle.setAttribute('aria-valuemax',typeof max==='function'?max():max);handle.setAttribute('aria-valuenow',Math.round(axis==='x'?target.getBoundingClientRect().width:target.getBoundingClientRect().height));handles.push({target,handle,id,apply});
  handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();const start=axis==='x'?e.clientX:e.clientY,size=axis==='x'?target.getBoundingClientRect().width:target.getBoundingClientRect().height;handle.setPointerCapture(e.pointerId);document.body.classList.add('resizing-panels');const move=event=>set(size+((axis==='x'?event.clientX:event.clientY)-start)*(reverse?-1:1));const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);document.body.classList.remove('resizing-panels');persist();};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);});
  handle.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const size=axis==='x'?target.getBoundingClientRect().width:target.getBoundingClientRect().height;set(size+(['ArrowLeft','ArrowUp'].includes(e.key)?-20:20));persist();}});handle.ondblclick=()=>{delete prefs[id];apply(null);handle.removeAttribute('aria-valuenow');persist();};
 }
 const aside=document.querySelector('.layout>aside'),layout=document.querySelector('.layout');grip({target:aside,name:'Largura do menu lateral',axis:'x',min:180,max:()=>Math.max(200,Math.min(620,window.innerWidth-430)),apply:n=>n?layout.style.setProperty('--sidebar-width',n+'px'):layout.style.removeProperty('--sidebar-width'),insert:h=>aside.after(h)});
 const chapters=document.createElement('section');chapters.className='resizable-sidebar-section';const head=aside.querySelector('.chapterhead'),nav=document.getElementById('chapters');head.before(chapters);chapters.append(head,nav);
 for(const [target,name]of [[aside.querySelector('.bookmeta'),'Altura dos dados do livro'],[chapters,'Altura da lista de capítulos'],[aside.querySelector('.importbox'),'Altura do painel de importação'],[document.querySelector('.advanced-tools'),'Altura das ferramentas de edição'],[document.getElementById('readerthumbnails'),'Altura das miniaturas do leitor'],[document.getElementById('editpagethumbs'),'Altura das miniaturas da edição']])if(target)grip({target,name,min:name.includes('miniaturas')?65:name.includes('ferramentas')?35:75,max:700,reverse:name.includes('miniaturas'),apply:n=>{target.style.height=n?n+'px':'';target.style.maxHeight=n?'none':'';target.style.overflow=n?'auto':'';},insert:h=>name.includes('miniaturas')?target.before(h):target.after(h)});
 const reset=document.createElement('button');reset.id='resetpanels';reset.textContent='↔ Restaurar tamanho dos painéis';reset.className='reset-panels';reset.onclick=()=>{prefs={};for(const item of handles){item.apply(null);item.handle.removeAttribute('aria-valuenow');}persist();};aside.append(reset);
}
